import pytz
import json
import re

from datetime import datetime
from taf.analyzer.base import LogEntry


class EmilLogEntry(LogEntry):
    """
    Provides methods to parse, represent Emil log entry object in readable format.

    Methods:

    - :meth:`message`: Provide message of a EmilLogEntry

    - :meth:`parse`: Provide EmilLogEntry object

    Attributes:

    - :attr:`timezone`: timezone offset
    - :attr:`message`: Emil Message

    """

    def __init__(self, message, **kwargs):
        """
        Create EmilLogEntry for a packet.

        :param Message message: Emil message as input
        """
        super(EmilLogEntry, self).__init__(**kwargs)
        self.__message = message

    def __str__(self):
        """
        Provides string representation of a EmilLogEntry

        :return: String representation of EmilLogEntry
        :rtype: str
        """
        result = json.dumps(
            {
                "timestamp": str(self.timestamp),
                "message": ""},
            indent=2)
        result = re.sub(r'""', '"""%s"""' % str(self.__message), result)
        return result

    @property
    def message(self):
        """
        Provide Message of EmilLogEntry

        :return: Emil message
        :rtype: Message
        """
        return self.__message

    @classmethod
    def parse(cls, timezone, message):
        """
        Provide EmilLogEntry object
        :param str timezone: timezone offset
        :param Message message: Emil message
        :return: EmilLogEntry object
        """
        time = datetime.fromisoformat(message.xpath("./Time")[0].ljust(26, '0')[:26])
        aware_timestamp = pytz.timezone(timezone).localize(time)
        return EmilLogEntry(
            message=message,
            timestamp=aware_timestamp
        )
